def match(pattern: str, text: str) -> bool:
    """
    This function implements basic regex matching using a recursive backtracking algorithm
    that handles literal characters, '.', '*', and '+'.
    """
    def is_match(i: int, j: int) -> bool:
        # If we reach the end of the pattern
        if i == len(pattern):
            return j == len(text)

        # Check for the next character being '*', '+' or a regular character
        if j < len(text) and (pattern[i] == text[j] or pattern[i] == '.'):
            # Check the next character in the pattern
            if (i + 1 < len(pattern) and pattern[i + 1] in '*+'):
                # Handle '*' (zero or more)
                if pattern[i + 1] == '*':
                    return (is_match(i, j + 1) or is_match(i + 2, j))
                # Handle '+' (one or more)
                elif pattern[i + 1] == '+':
                    return is_match(i, j + 1) or is_match(i + 2, j)
            else:
                return is_match(i + 1, j + 1)

        # Handle '*' (zero or more) and '+' (one or more)
        if i + 1 < len(pattern) and pattern[i + 1] == '*':
            return is_match(i + 2, j) or (j < len(text) and is_match(i, j + 1))
        if i + 1 < len(pattern) and pattern[i + 1] == '+':
            return j < len(text) and is_match(i + 2, j + 1)

        return False

    return is_match(0, 0)

