    """
    This function implements basic regex matching using dynamic programming.
    It constructs a table to store results of subproblems and iteratively fills it
    based on whether the current characters match and the handling of special regex characters.
    """
    m, n = len(pattern), len(text)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    for i in range(1, m + 1):
        if pattern[i - 1] == '*':
            dp[i][0] = dp[i - 2][0]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if pattern[i - 1] == text[j - 1] or pattern[i - 1] == '.':
                dp[i][j] = dp[i - 1][j - 1]
            elif pattern[i - 1] == '*':
                dp[i][j] = dp[i - 2][j] or (dp[i][j - 1] and (pattern[i - 2] == text[j - 1] or pattern[i - 2] == '.'))
            elif pattern[i - 1] == '+':
                dp[i][j] = dp[i - 1][j] and (pattern[i - 2] == text[j - 1] or pattern[i - 2] == '.')

    return dp[m][n]

