    This function implements basic regex matching using an iterative two-pointer approach.
    It traverses both the pattern and text using two pointers, handling literal characters, 
    '.', '*', and '+' while backtracking as necessary through the pattern if needed.
    """
    p_len, t_len = len(pattern), len(text)
    p_index, t_index = 0, 0

    while p_index < p_len:
        if p_index + 1 < p_len and pattern[p_index + 1] in '*+':
            # Handle '*' and '+'
            quantifier = pattern[p_index + 1]
            if quantifier == '*':
