                    if match(pattern[p_index + 2:], text[t_index:]):
                        return True
                    t_index += 1
                p_index += 2
            elif quantifier == '+':
                if t_index < t_len and (pattern[p_index] == text[t_index] or pattern[p_index] == '.'):
                    while t_index < t_len and (pattern[p_index] == text[t_index] or pattern[p_index] == '.'):
                        if match(pattern[p_index + 2:], text[t_index + 1:]):
                            return True
                        t_index += 1
                return False  # No match for '+'
        else:
            # Regular character or '.'
            if t_index < t_len and (pattern[p_index] == text[t_index] or pattern[p_index] == '.'):
                p_index += 1
                t_index += 1
            else:
                return False

    return t_index == t_len

